use verus::prelude::*;

verus! {

    #[verus]
    pub fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        // the result vector has the same length as the input
        ensures result.len() == a.len()
        // and each element in result equals the corresponding one in a
        ensures forall(|i: usize| i < a.len() ==> result[i] == a[i])
    {
        // start with an empty vector
        let mut result: Vec<T> = Vec::new();
        let mut i: usize = 0;

        // copy elements one by one
        while i < a.len() {
            invariant
                // i never exceeds the original length
                i <= a.len(),
                // result has exactly i elements so far
                result.len() == i,
                // and those i elements exactly match a[0..i]
                forall(|j: usize| j < i ==> result[j] == a[j]);
            decreases a.len() - i;

            // body: push the next element
            result.push(a[i]);
            i += 1;
        }

        // return the fully‐built vector
        result
    }

}